/*
The problem statement provided is incomplete, so this solution implements the
natural interpretation:

- Input begins with two integers:
    C N
  where C = number of coaster images, N = image size (N x N).

- The first coaster is given as N lines, each containing N characters
  representing pixels.

- Each subsequent coaster is given by:
    K
    followed by K pairs:
      r c
  meaning the pixel at row r, column c changed from the previous image.
  Coordinates are assumed to be 0-based. If your judge uses 1-based indices,
  change the two decrements in the update loop accordingly.

- A coaster is counted if its image is both horizontally symmetric
  (mirror across the horizontal middle line) and vertically symmetric
  (mirror across the vertical middle line).

This is done efficiently by maintaining mismatch counts for both symmetries and
updating only affected pairs after each toggle.
*/

static int idx(int r, int c, int n) {
    return r * n + c;
}

int main(void) {
    int C, N;
    if (scanf("%d %d", &C, &N) != 2) return 0;

    char *grid = (char *)malloc((size_t)N * N);
    char *line = (char *)malloc((size_t)N + 5);
    if (!grid || !line) return 0;

    for (int i = 0; i < N; i++) {
        if (scanf("%s", line) != 1) return 0;
        for (int j = 0; j < N; j++) {
            grid[idx(i, j, N)] = line[j];
        }
    }

    long long vbad = 0; /* vertical symmetry mismatches */
    long long hbad = 0; /* horizontal symmetry mismatches */

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N / 2; j++) {
            if (grid[idx(i, j, N)] != grid[idx(i, N - 1 - j, N)]) vbad++;
        }
    }

    for (int i = 0; i < N / 2; i++) {
        for (int j = 0; j < N; j++) {
            if (grid[idx(i, j, N)] != grid[idx(N - 1 - i, j, N)]) hbad++;
        }
    }

    long long ans = (vbad == 0 && hbad == 0) ? 1 : 0;

    for (int img = 1; img < C; img++) {
        int K;
        if (scanf("%d", &K) != 1) return 0;

        for (int t = 0; t < K; t++) {
            int r, c;
            if (scanf("%d %d", &r, &c) != 2) return 0;

            /* If coordinates are 1-based in the actual judge input, uncomment:
               r--; c--;
            */

            int p = idx(r, c, N);

            /* Remove old contributions */
            int vc = N - 1 - c;
            if (vc != c) {
                if (grid[p] != grid[idx(r, vc, N)]) vbad--;
            }

            int hr = N - 1 - r;
            if (hr != r) {
                if (grid[p] != grid[idx(hr, c, N)]) hbad--;
            }

            /* Toggle the pixel. Assumes binary-like pixels, common chars:
               '.' <-> '#', '0' <-> '1'. Fallback toggles between '0' and '1'. */
            if (grid[p] == '.') grid[p] = '#';
            else if (grid[p] == '#') grid[p] = '.';
            else if (grid[p] == '0') grid[p] = '1';
            else if (grid[p] == '1') grid[p] = '0';
            else grid[p] = (grid[p] == 'X' ? '.' : 'X');

            /* Add new contributions */
            if (vc != c) {
                if (grid[p] != grid[idx(r, vc, N)]) vbad++;
            }
            if (hr != r) {
                if (grid[p] != grid[idx(hr, c, N)]) hbad++;
            }
        }

        if (vbad == 0 && hbad == 0) ans++;
    }

    printf("%lld\n", ans);

    free(grid);
    free(line);
    return 0;
}

