    static boolean isSymmetrical(boolean[][] grid, int n) {
        // Check horizontal symmetry (left-right)
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n / 2; j++) {
                if (grid[i][j] != grid[i][n - 1 - j]) {
                    return false;
                }
            }
        }
        // Check vertical symmetry (top-bottom)
        for (int i = 0; i < n / 2; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] != grid[n - 1 - i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());

        boolean[][] grid = new boolean[n][n];
        int count = 0;

        // Read first coaster (complete image)
        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            for (int j = 0; j < n; j++) {
                grid[i][j] = (line.charAt(j) == '1');
            }
        }
        if (isSymmetrical(grid, n)) count++;

        // Process remaining coasters as differences
        for (int c = 1; c < k; c++) {
            int changes = Integer.parseInt(br.readLine().trim());
