import java.io.*;
import java.util.*;

public class Main {
    // Fast input
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        String next() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            StringBuilder sb = new StringBuilder();
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int n;
        try {
            n = fs.nextInt();
        } catch (Exception e) {
            return;
        }
        int m = fs.nextInt();

        boolean[][] a = new boolean[n][n];

        // mismatch counts for symmetry
        // vertical: compare (r,c) with (r,n-1-c), only c < n/2
        // horizontal: compare (r,c) with (n-1-r,c), only r < n/2
        int vertBad = 0;
        int horiBad = 0;

        // read first full image
        for (int i = 0; i < n; i++) {
            String s = fs.next();
            for (int j = 0; j < n; j++) {
                a[i][j] = s.charAt(j) == '1' || s.charAt(j) == '#' || s.charAt(j) == 'X' || s.charAt(j) == '*';
            }
        }

        // initialize mismatch counts
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n / 2; j++) {
                if (a[i][j] != a[i][n - 1 - j]) vertBad++;
            }
        }
        for (int i = 0; i < n / 2; i++) {
            for (int j = 0; j < n; j++) {
                if (a[i][j] != a[n - 1 - i][j]) horiBad++;
            }
        }

        int ans = (vertBad == 0 && horiBad == 0) ? 1 : 0;

        // process remaining m-1 coasters as diffs
        for (int img = 1; img < m; img++) {
            int k = fs.nextInt();
            for (int t = 0; t < k; t++) {
                int r = fs.nextInt() - 1;
                int c = fs.nextInt() - 1;

                // remove old contribution for vertical pair containing (r,c)
                int vc = Math.min(c, n - 1 - c);
                if (vc != n - 1 - vc) {
                    if (a[r][vc] != a[r][n - 1 - vc]) vertBad--;
                }

                // remove old contribution for horizontal pair containing (r,c)
                int hr = Math.min(r, n - 1 - r);
                if (hr != n - 1 - hr) {
                    if (a[hr][c] != a[n - 1 - hr][c]) horiBad--;
                }

                // toggle pixel
                a[r][c] = !a[r][c];

                // add new contribution
                if (vc != n - 1 - vc) {
                    if (a[r][vc] != a[r][n - 1 - vc]) vertBad++;
                }
                if (hr != n - 1 - hr) {
                    if (a[hr][c] != a[n - 1 - hr][c]) horiBad++;
                }
            }

            if (vertBad == 0 && horiBad == 0) ans++;
        }

        System.out.println(ans);
    }
}

