import sys

def is_symmetric(grid, n):
    # Check horizontal symmetry (left-right)
    for i in range(n):
        for j in range(n // 2):
            if grid[i][j] != grid[i][n-1-j]:
                return False
    # Check vertical symmetry (top-bottom)
    for i in range(n // 2):
        for j in range(n):
            if grid[i][j] != grid[n-1-i][j]:
                return False
    return True

